rooms=['crescent_court','vaulted_lanes','circular_bath'];ds={phase:{r:json.loads((root/phase/(r+'.json')).read_text()) for r in rooms}for phase in ['baseline','candidate']}
with (root/'contact_foot_regions.csv').open('w')as f:
 fields=['phase','room','object','kind','region','base_y','sample_count','contact_count','gap_min_m','gap_max_m','receivers'];w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
 for phase,data in ds.items():
  for room,d in data.items():
   for c in d['contacts']:
    groups=[('whole base',c['samples'])]
    if c['kind']in['arch_feet','bench_feet']:
     span=[max(s['foot'][i]for s in c['samples'])-min(s['foot'][i]for s in c['samples'])for i in [0,2]];axis=[0,2][span.index(max(span))];mid=(max(s['foot'][axis]for s in c['samples'])+min(s['foot'][axis]for s in c['samples']))/2
     groups=[(('X'if axis==0 else'Z')+side,[s for s in c['samples']if(s['foot'][axis]<mid)==(side=='-')])for side in['-','+']]
